import json

# Load the JSON data
with open('/app/resources/treasury_bulletin_2000_09.json', 'r') as f:
    data = json.load(f)

# Let's explore the structure
def explore(obj, path=""):
    if isinstance(obj, dict):
        for k, v in obj.items():
            explore(v, f"{path}.{k}")
    elif isinstance(obj, list):
        if len(obj) > 0:
            explore(obj[0], f"{path}[0]")
    else:
        pass

# Try to find debt-related tables
for key in data:
    print(f"Key: {key}")
